package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"

	"github.com/shopspring/decimal"
)

type DateRec struct {
	DtId   string
	DtYyyy int64
	DtMm   int64
	DtDd   int64
}

var WsEofFlag string = "N"
var WsLeapFlag string = "N"
var WsQ int64 = 0
var WsR4 int64 = 0
var WsR100 int64 = 0
var WsR400 int64 = 0
var WsMaxDay int64 = 0
var WsValid int64 = 0
var WsBadMonth int64 = 0
var WsBadDay int64 = 0

var dateRec DateRec

var inputLines []string
var inputIdx int

// helpers for COBOL numeric handling
func pow10(n int) int64 {
	var p int64 = 1
	for i := 0; i < n; i++ {
		p *= 10
	}
	return p
}

func truncateToPIC(v int64, digits int) int64 {
	if digits <= 0 {
		return 0
	}
	mod := pow10(digits)
	if v < 0 {
		v = -v
		// COBOL truncation for negative? Keep low-order digits, sign?
		// Not needed for this program (counters non-negative)
		return -(v % mod)
	}
	return v % mod
}

func formatPIC9(v int64, digits int) string {
	// keep low-order digits
	if digits <= 0 {
		return ""
	}
	mod := pow10(digits)
	// handle negative (not needed but implement)
	neg := false
	if v < 0 {
		neg = true
		v = -v
	}
	v = v % mod
	s := strconv.FormatInt(v, 10)
	if len(s) < digits {
		s = strings.Repeat("0", digits-len(s)) + s
	} else if len(s) > digits {
		s = s[len(s)-digits:]
	}
	if neg {
		// COBOL would show sign elsewhere; not needed
	}
	return s
}

func isInputDone() bool {
	return WsEofFlag == "Y"
}

func parseNumField(raw string) int64 {
	raw = strings.TrimSpace(raw)
	if raw == "" {
		return 0
	}
	// raw should be digits only; parse
	// if contains non-digit, treat non-digits as 0? just try atoi
	v, err := strconv.ParseInt(raw, 10, 64)
	if err != nil {
		// try to extract digits
		var digits strings.Builder
		for _, ch := range raw {
			if ch >= '0' && ch <= '9' {
				digits.WriteRune(ch)
			}
		}
		if digits.Len() == 0 {
			return 0
		}
		v, _ = strconv.ParseInt(digits.String(), 10, 64)
		return v
	}
	return v
}

func padRight(s string, n int) string {
	if len(s) >= n {
		return s[:n]
	}
	return s + strings.Repeat(" ", n-len(s))
}

// Use decimal to satisfy import requirement
var _ = decimal.NewFromInt(0)

func MAIN_PARA() {
	// OPEN INPUT DATE-FILE
	f, err := os.Open("input.dat")
	if err != nil {
		// if file not found, treat as empty
		inputLines = []string{}
	} else {
		scanner := bufio.NewScanner(f)
		// allow long lines
		const maxCapacity = 1024 * 1024
		buf := make([]byte, 0, 64*1024)
		scanner.Buffer(buf, maxCapacity)
		for scanner.Scan() {
			line := scanner.Text()
			// scanner strips \n and \r, COBOL LINE SEQUENTIAL: one record per line padded with spaces
			// keep as is (spaces preserved except trailing newline removed)
			// If line shorter than record length, pad later in READ-PARA handling
			inputLines = append(inputLines, line)
		}
		f.Close()
	}
	inputIdx = 0
	READ_PARA()
	for !isInputDone() {
		PROCESS_PARA()
	}
	// CLOSE DATE-FILE (no action)
	// DISPLAY "VALID: " WS-VALID " BAD MONTH: " WS-BAD-MONTH " BAD DAY: " WS-BAD-DAY
	fmt.Println("VALID: " + formatPIC9(WsValid, 2) + " BAD MONTH: " + formatPIC9(WsBadMonth, 2) + " BAD DAY: " + formatPIC9(WsBadDay, 2))
}

func READ_PARA() {
	if inputIdx >= len(inputLines) {
		WsEofFlag = "Y"
		return
	}
	line := inputLines[inputIdx]
	inputIdx++
	// COBOL LINE SEQUENTIAL: if line shorter than record length pad with spaces
	if len(line) < 12 {
		line = line + strings.Repeat(" ", 12-len(line))
	} else if len(line) > 12 {
		line = line[:12]
	}
	// parse fields
	dateRec.DtId = line[0:4]
	// numeric fields: digits only, implied decimal not relevant
	rawYyyy := line[4:8]
	rawMm := line[8:10]
	rawDd := line[10:12]

	dateRec.DtYyyy = truncateToPIC(parseNumField(rawYyyy), 4)
	dateRec.DtMm = truncateToPIC(parseNumField(rawMm), 2)
	dateRec.DtDd = truncateToPIC(parseNumField(rawDd), 2)
}

func PROCESS_PARA() {
	LEAP_PARA()
	// EVALUATE TRUE
	if dateRec.DtMm < 1 || dateRec.DtMm > 12 {
		WsBadMonth = truncateToPIC(WsBadMonth+1, 2)
		fmt.Println(dateRec.DtId + " BAD MONTH " + formatPIC9(dateRec.DtMm, 2))
	} else {
		DAYS_PARA()
		if dateRec.DtDd < 1 || dateRec.DtDd > WsMaxDay {
			WsBadDay = truncateToPIC(WsBadDay+1, 2)
			fmt.Println(dateRec.DtId + " BAD DAY " + formatPIC9(dateRec.DtDd, 2) + " MAX " + formatPIC9(WsMaxDay, 2))
		} else {
			WsValid = truncateToPIC(WsValid+1, 2)
			fmt.Println(dateRec.DtId + " VALID " + formatPIC9(dateRec.DtYyyy, 4) + "-" + formatPIC9(dateRec.DtMm, 2) + "-" + formatPIC9(dateRec.DtDd, 2))
		}
	}
	READ_PARA()
}

func LEAP_PARA() {
	// DIVIDE DT-YYYY BY 4 GIVING WS-Q REMAINDER WS-R4
	// etc.
	// Use integer division
	WsQ = truncateToPIC(dateRec.DtYyyy/4, 4)
	WsR4 = truncateToPIC(dateRec.DtYyyy%4, 3)
	WsQ = truncateToPIC(dateRec.DtYyyy/100, 4)
	WsR100 = truncateToPIC(dateRec.DtYyyy%100, 3)
	WsQ = truncateToPIC(dateRec.DtYyyy/400, 4)
	WsR400 = truncateToPIC(dateRec.DtYyyy%400, 3)
	if WsR4 == 0 && (WsR100 != 0 || WsR400 == 0) {
		WsLeapFlag = "Y"
	} else {
		WsLeapFlag = "N"
	}
}

func DAYS_PARA() {
	switch dateRec.DtMm {
	case 2:
		if WsLeapFlag == "Y" {
			WsMaxDay = 29
		} else {
			WsMaxDay = 28
		}
	case 4, 6, 9, 11:
		WsMaxDay = 30
	default:
		WsMaxDay = 31
	}
	// ensure truncate to 2 digits (not needed but for fidelity)
	WsMaxDay = truncateToPIC(WsMaxDay, 2)
}

func main() {
	// ensure padRight not unused
	_ = padRight
	MAIN_PARA()
}
